239: export function candidate01FxPicture(topic: string): BoardPicture {
240:   const record = candidate01Asset(topic);
241:   const frameWidth = record.frameWidth ?? 32;
242:   const frameHeight = record.frameHeight ?? 32;
243:   const frames = record.frames ?? 1;
244:   const anchor = record.anchor;
245:   if (!anchor || anchor.length !== 2
246:     || !Number.isFinite(anchor[0]) || anchor[0] < 0 || anchor[0] >= frameWidth
247:     || !Number.isFinite(anchor[1]) || anchor[1] < 0 || anchor[1] >= frameHeight) {
248:     throw new Error(`candidate-01 effect has no valid anchor: ${topic}`);
249:   }
250:   return {
251:     body: '',
252:     strip: {
253:       href: record.url,
254:       frameWidth,
255:       frameHeight,
256:       frameCount: frames,
257:       x: -anchor[0],
258:       y: -anchor[1],
259:       clips: [{
260:         id: 'effect',
261:         frames: Array.from({ length: frames }, (_, frame) => frame),
262:         fps: record.fps ?? 12,
263:         loop: record.loop ?? false,
264:       }],
265:       playing: 'effect',
266:     },
267:   };
268: }
